package com.hmdp.ai.infrastructure.mcp;import com.hmdp.ai.domain.mcp.*;import org.springframework.stereotype.Component;@Component public class McpServerRegistry {private final McpRepository repository;public McpServerRegistry(McpRepository repository){this.repository=repository;}public McpServer require(String tenant,String workspace,String id){McpServer s=repository.find(tenant,workspace,id).orElseThrow(()->new IllegalArgumentException("MCP_SERVER_NOT_FOUND"));if(!s.isEnabled())throw new IllegalArgumentException("MCP_SERVER_DISABLED");return s;}}
